from datetime import datetime, timezone
import json
import re

from ollama import Client
from pydantic import BaseModel, ConfigDict, Field
from typing import Literal
from trading_agent.ollama_client import get_client, get_model

from trading_agent.schemas import MarketSnapshot, ResearchReport
from rich.console import Console

console = Console()

class ResearchDraft(BaseModel):
    """Fields generated by the language model."""

    model_config = ConfigDict(extra="forbid")

    horizon: str = "1–4 weeks"

    stance: Literal["bullish", "bearish", "neutral"] = "neutral"

    thesis: str

    supporting_evidence: list[str] = Field(default_factory=list)
    counter_evidence: list[str] = Field(default_factory=list)
    risks: list[str] = Field(default_factory=list)
    invalidation_conditions: list[str] = Field(default_factory=list)

    confidence: Literal["low", "medium", "high"] = "low"

    missing_information: list[str] = Field(default_factory=list)

    action: Literal[
        "watch",
        "investigate_further",
        "no_action",
    ] = "no_action"


def generate_research_report(
    snapshot: MarketSnapshot,
    model_name: str,
) -> ResearchReport:
    """Generate a structured report from existing market metrics."""

    market_data = json.dumps(
        snapshot.model_dump(mode="json"),
        indent=2,
    )

    messages = [
        {
            "role": "system",
            "content": (
                "You are a cautious financial research assistant. "
                "Analyze only the market data supplied by the user. "
                "Do not invent prices, news, earnings, financial statements, "
                "or other evidence that is not provided. "
                "Distinguish observed facts from interpretation. "
                "Technical indicators alone do not establish that a stock "
                "is a good investment. "
                "If information is insufficient, state what is missing, "
                "use low confidence, and choose no_action. "
                "Do not recommend executing trades."
            ),
        },
        {
            "role": "user",
            "content": (
                "Generate a structured research draft using this market data.\n\n"
                f"{market_data}\n\n"
                "Put important evidence and counter-evidence in separate lists. "
                "Mention missing fundamental, valuation, and news information "
                "when those sources were not supplied. "
                "Return only the fields required by the provided schema."
            ),
        },
    ]

    schema_json = json.dumps(
        ResearchDraft.model_json_schema(),
        indent=2,
    )

    messages[1]["content"] += (
        "\n\nYour response must conform to this JSON Schema:\n"
        f"{schema_json}\n\n"
        "Return one valid JSON object only. "
        "Do not use Markdown code fences. "
        "Use exactly the schema's property names. "
        "Do not add extra fields."
    )

    response = get_client().chat(
        model=get_model(),
        messages=messages,
        options={"temperature": 0},
    )

    console.print(response)

    raw_content = response.message.content
    console.print("------raw_content------")
    console.print(repr(raw_content))

    cleaned_content = extract_json(raw_content)
    console.print("------cleaned_content------")
    console.print(repr(cleaned_content))
    
    # This still rejects missing fields, incorrect types and unexpected keys.
    draft = ResearchDraft.model_validate_json(cleaned_content)

    # Parse the model's response and validate its structure and types.
    draft = ResearchDraft.model_validate_json(
        response.message.content
    )

    # Python, not the model, supplies the report metadata.
    report = ResearchReport(
        ticker=snapshot.ticker,
        as_of=datetime.now(timezone.utc),
        **draft.model_dump(),
    )

    return report


def extract_json(text: str) -> str:
    """Extract a JSON object from raw JSON or a Markdown code fence."""
    text = text.strip()

    # Remove an opening ```json or ``` fence.
    text = re.sub(
        r"\A```(?:json)?\s*",
        "",
        text,
        flags=re.IGNORECASE,
    )

    # Remove the closing fence.
    text = re.sub(r"\s*```\s*\Z", "", text)

    return text.strip()
